begin;
create table if not exists public.mme_financial_periods(financial_period_id uuid primary key default gen_random_uuid(),period_name text not null unique,period_start date not null,period_end date not null,period_status text not null default 'open' check(period_status in('open','review','closed','locked')),created_by_auth_user_id uuid not null,closed_by_auth_user_id uuid,closed_at timestamptz,created_at timestamptz not null default now(),check(period_end>=period_start));
create table if not exists public.mme_chart_of_accounts(account_id uuid primary key default gen_random_uuid(),account_code text not null unique,account_name text not null,account_type text not null check(account_type in('asset','liability','equity','revenue','expense')),normal_balance text not null check(normal_balance in('debit','credit')),parent_account_id uuid references public.mme_chart_of_accounts(account_id),is_control_account boolean not null default false,is_active boolean not null default true,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_journal_entries(journal_entry_id uuid primary key default gen_random_uuid(),entry_number text not null unique,financial_period_id uuid not null references public.mme_financial_periods(financial_period_id),entry_date date not null,description text not null,source_module text not null default 'manual',source_reference text,entry_status text not null default 'draft' check(entry_status in('draft','submitted','approved','posted','reversed','voided')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,posted_by_auth_user_id uuid,posted_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.mme_journal_entry_lines(journal_line_id uuid primary key default gen_random_uuid(),journal_entry_id uuid not null references public.mme_journal_entries(journal_entry_id) on delete restrict,account_id uuid not null references public.mme_chart_of_accounts(account_id),line_description text,debit numeric(16,2) not null default 0 check(debit>=0),credit numeric(16,2) not null default 0 check(credit>=0),created_at timestamptz not null default now(),check((debit>0 and credit=0) or (credit>0 and debit=0)));
create index if not exists mme_journal_lines_entry_idx on public.mme_journal_entry_lines(journal_entry_id);
create table if not exists public.mme_financial_approval_events(approval_event_id uuid primary key default gen_random_uuid(),subject_type text not null,subject_id uuid not null,decision text not null check(decision in('approved','rejected','posted','voided')),note text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_financial_vendors(vendor_id uuid primary key default gen_random_uuid(),vendor_code text not null unique,vendor_name text not null,tax_reference_last4 text,contact_email text,payment_terms text,vendor_status text not null default 'active' check(vendor_status in('active','inactive','blocked')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_accounts_payable_bills(ap_bill_id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.mme_financial_vendors(vendor_id),vendor_invoice_number text not null,invoice_date date not null,due_date date not null,amount numeric(16,2) not null check(amount>0),currency_code char(3) not null default 'USD',bill_status text not null default 'draft' check(bill_status in('draft','submitted','approved','partially_paid','paid','voided')),source_document_path text,created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),unique(vendor_id,vendor_invoice_number),check(due_date>=invoice_date));
create table if not exists public.mme_accounts_receivable_invoices(ar_invoice_id uuid primary key default gen_random_uuid(),customer_reference text not null,invoice_number text not null unique,invoice_date date not null,due_date date not null,amount numeric(16,2) not null check(amount>0),currency_code char(3) not null default 'USD',invoice_status text not null default 'draft' check(invoice_status in('draft','issued','partially_paid','paid','voided')),source_reference text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(due_date>=invoice_date));
create table if not exists public.mme_financial_payments(payment_id uuid primary key default gen_random_uuid(),payment_direction text not null check(payment_direction in('inbound','outbound')),ap_bill_id uuid references public.mme_accounts_payable_bills(ap_bill_id),ar_invoice_id uuid references public.mme_accounts_receivable_invoices(ar_invoice_id),payment_method text not null check(payment_method in('ach','check','card','cash','wire','other')),amount numeric(16,2) not null check(amount>0),currency_code char(3) not null default 'USD',payment_status text not null default 'pending' check(payment_status in('pending','submitted','confirmed','failed','voided')),provider_reference text,paid_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check((ap_bill_id is not null)::int+(ar_invoice_id is not null)::int=1));
create table if not exists public.mme_bank_reconciliation_sessions(reconciliation_id uuid primary key default gen_random_uuid(),account_id uuid not null references public.mme_chart_of_accounts(account_id),statement_start date not null,statement_end date not null,opening_balance numeric(16,2) not null,closing_balance numeric(16,2) not null,reconciled_balance numeric(16,2),reconciliation_status text not null default 'draft' check(reconciliation_status in('draft','in_progress','balanced','approved','discrepancy')),approved_by_auth_user_id uuid,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(statement_end>=statement_start));
create table if not exists public.mme_financial_expenses(expense_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid references public.mme_employee_profiles(employee_auth_user_id),expense_category text not null,description text not null,amount numeric(16,2) not null check(amount>0),currency_code char(3) not null default 'USD',expense_date date not null,receipt_path text,expense_status text not null default 'submitted' check(expense_status in('submitted','approved','rejected','reimbursed')),reviewed_by_auth_user_id uuid,created_at timestamptz not null default now());
create table if not exists public.mme_purchase_orders(purchase_order_id uuid primary key default gen_random_uuid(),po_number text not null unique,vendor_id uuid not null references public.mme_financial_vendors(vendor_id),order_date date not null,expected_date date,total_amount numeric(16,2) not null check(total_amount>=0),currency_code char(3) not null default 'USD',po_status text not null default 'draft' check(po_status in('draft','submitted','approved','sent','partially_received','received','cancelled')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now());
create table if not exists public.mme_financial_audit_events(financial_audit_event_id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,action text not null,actor_auth_user_id uuid not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['mme_financial_periods','mme_chart_of_accounts','mme_journal_entries','mme_journal_entry_lines','mme_financial_approval_events','mme_financial_vendors','mme_accounts_payable_bills','mme_accounts_receivable_invoices','mme_financial_payments','mme_bank_reconciliation_sessions','mme_financial_expenses','mme_purchase_orders','mme_financial_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;

create or replace function public.mme_post_financial_journal(p_entry_id uuid,p_actor uuid)
returns jsonb language plpgsql security definer set search_path=public as $
declare e public.mme_journal_entries%rowtype; totals record;
begin
 select * into e from public.mme_journal_entries where journal_entry_id=p_entry_id for update;
 if not found then raise exception 'journal_entry_not_found'; end if;
 if e.entry_status not in ('draft','approved') then raise exception 'journal_entry_not_postable'; end if;
 if e.created_by_auth_user_id=p_actor then raise exception 'separation_of_duties_required'; end if;
 if not exists(select 1 from public.mme_financial_periods p where p.financial_period_id=e.financial_period_id and p.period_status='open' and e.entry_date between p.period_start and p.period_end) then raise exception 'financial_period_not_open'; end if;
 select coalesce(sum(debit),0) debit_total,coalesce(sum(credit),0) credit_total,count(*) line_count into totals from public.mme_journal_entry_lines where journal_entry_id=p_entry_id;
 if totals.line_count<2 or totals.debit_total<=0 or totals.debit_total<>totals.credit_total then raise exception 'journal_entry_not_balanced'; end if;
 update public.mme_journal_entries set entry_status='posted',posted_by_auth_user_id=p_actor,posted_at=now(),approved_by_auth_user_id=coalesce(approved_by_auth_user_id,p_actor) where journal_entry_id=p_entry_id;
 insert into public.mme_financial_approval_events(subject_type,subject_id,decision,actor_auth_user_id) values('journal_entry',p_entry_id,'posted',p_actor);
 insert into public.mme_financial_audit_events(entity_type,entity_id,action,actor_auth_user_id,metadata) values('journal_entry',p_entry_id,'posted',p_actor,jsonb_build_object('debit_total',totals.debit_total,'credit_total',totals.credit_total));
 return jsonb_build_object('journal_entry_id',p_entry_id,'status','posted','debit_total',totals.debit_total,'credit_total',totals.credit_total);
end;$;
revoke all on function public.mme_post_financial_journal(uuid,uuid) from public,anon,authenticated;
grant execute on function public.mme_post_financial_journal(uuid,uuid) to service_role;
commit;